"""Compatibility implementation of the Meridian CRM division semantics."""

from __future__ import annotations

from typing import Any


def _legacy_number(value: Any) -> float:
    """Coerce a value using the legacy numeric rules."""
    if value is None:
        return 0.0
    if isinstance(value, str):
        if value.strip() == "":
            return 0.0
    try:
        return float(value)
    except (TypeError, ValueError, OverflowError):
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """Divide using legacy CRMScript semantics.

    Division by a value that coerces to zero returns 0.0 and emits one
    SCRIPT_DIV0 audit code.
    """
    numerator = _legacy_number(a)
    denominator = _legacy_number(b)

    if denominator == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    try:
        return numerator / denominator, []
    except (ArithmeticError, OverflowError):
        return 0.0, ["SCRIPT_DIV0"]
